matchMedia('(prefers-color-scheme: light)').addEventListener('change',()=>{if(db.settings.theme==='system')applySettings();});api?.onStatus(handleStatus);api?.onCommand(name=>command(name).catch(e=>toast(e.message,true)));
(async()=>{try{if(!api)throw Error('Запустите VKSound через Start-App.cmd, а не HTML-файл.');await snapshot();musicState.total=db.library.length;await handleStatus(await call('state'));if(typeof restorePlaybackQueue==='function')await restorePlaybackQueue();if(db.warning)toast(db.warning,true);}catch(e){render();toast(e.message,true);}})();

$('clearPlaylist').onclick=action(clearCurrentPlaylist);$('mixLaunch').onclick=action(startMix);$('vkQuery').addEventListener('input',()=>{$('clearSearch').hidden=!$('vkQuery').value;if(route==='search'&&!$('vkQuery').value.trim()){loadTicket++;loading=false;searchState={query:'',keys:[],total:0,next:0};selectedKeys.clear();if(typeof resetArtistSearch==='function')resetArtistSearch();if(typeof resetPlaylistSearch==='function')resetPlaylistSearch();render();if(typeof renderExperience==='function')renderExperience();}});$('vkQuery').addEventListener('paste',event=>{const value=event.clipboardData?.getData('text')?.trim();if(!value)return;try{const u=new URL(value);if(u.protocol==='https:'&&['vk.com','www.vk.com','m.vk.com','vk.ru','www.vk.ru','m.vk.ru'].includes(u.hostname.toLowerCase()))setTimeout(()=>$('globalSearch').requestSubmit(),0);}catch{}});$('clearSearch').onclick=()=>{$('vkQuery').value='';$('clearSearch').hidden=true;$('vkQuery').dispatchEvent(new Event('input'));$('vkQuery').focus();};

function updateQueueArtwork(){const key=queueArtworkKey||'',identity=[key,db.coverRevision||0,db.coverBase||''].join('|'),button=$('queueButton');if(button.dataset.artwork!=='list-icon'){button.dataset.artwork='list-icon';button.replaceChildren(icon('list'));}const open=$('queueCardOpen');if(open.dataset.artwork!==identity){open.dataset.artwork=identity;const old=open.querySelector('.queue-rail-icon'),visual=key?coverArt(key,'list'):icon('list');visual.classList.add('queue-rail-icon');if(key)visual.classList.add('queue-card-art');if(old)old.replaceWith(visual);else open.prepend(visual);}}
function renderQueueShortcut(){const slot=$('queueCardSlot'),visible=queueStarted&&q.keys.length>0;if(!visible&&slot.contains(document.activeElement))$('main').focus();queueReveal.set(visible);$('queueCardSubtitle').textContent=counted(q.keys.length)+(db.rows[current]?' · '+db.rows[current].title:'');if(!$('queueCardToggle').querySelector('.queue-cd'))$('queueCardToggle').replaceChildren(make('span','queue-cd'));$('queueCardToggle').classList.toggle('is-playing',!audio.paused);updateQueueArtwork();if(typeof renderQueueCover==='function')renderQueueCover();$('queueCardToggle').setAttribute('aria-label',audio.paused?'Продолжить текущий плейлист':'Приостановить текущий плейлист');}
async function clearCurrentQueue(){stopLocal();await call('stop');if(route==='queue')go('music');else render();}
$('queueCardToggle').onclick=action(()=>command('toggle'));$('queueCardOpen').onclick=()=>go('queue');$('queueCardClear').onclick=action(clearCurrentQueue);
$('mixDiagnostics').onclick=action(async()=>{await call('mixDiagnostics');toast('Диагностика скопирована. Токены и личные данные не включены.');});

function publishPlayerState(){if(!api?.playerState||(uiDormant&&!miniVisible))return;const payload={key:current,playing:!!current&&!audio.paused,canStart:!!current||q.keys.length>0||db.library.some(k=>canPlay(db.rows[k])),previous:!!current,next:!!current&&(q.keys.length>1||(mixPlayback&&mixMore)),volume:audio.volume*100,elapsed:Number.isFinite(audio.currentTime)?audio.currentTime:0,duration:Number.isFinite(audio.duration)?audio.duration:0,canSeek:!!current&&Number.isFinite(audio.duration)&&audio.duration>0&&audio.seekable.length>0,peaks:fx.peaks.get(current)||[],theme:document.documentElement.dataset.theme,colors:coverPalette,eq:equalizer.settings.enabled};const signature=JSON.stringify([payload,db.settings.accent,db.settings.equalizer?.enabled,db.coverRevision,db.coverBase,db.rows[current]?.title,db.rows[current]?.artist,db.rows[current]?.coverKey]);if(signature===lastMiniSignature)return;lastMiniSignature=signature;call('playerState',payload).catch(()=>{});}
function syncVolumeControl(n){const value=Math.round(Math.max(0,Math.min(100,Number(n)||0))),muted=value===0,wrap=$('volume')?.closest('.volume'),buttons=[$('volumeMute'),$('fullVolumeMute')];if($('volume'))$('volume').value=value;if($('fullVolume'))$('fullVolume').value=value;if($('fullVolumeValue'))$('fullVolumeValue').textContent=value+'%';if(wrap)wrap.dataset.volume=value+'%';for(const button of buttons)if(button){button.replaceChildren(icon(muted?'volume-muted':'volume'));button.setAttribute('aria-label',muted?'Включить звук':'Отключить звук');button.title=muted?'Включить звук':'Отключить звук';button.setAttribute('aria-pressed',String(muted));}}
function setPlayerVolume(n){if(!Number.isFinite(n)||n<0||n>100)return;if(n>0)lastNonZeroVolume=n;audio.volume=n/100;db.settings.volume=n;volumeDraft=n;syncVolumeControl(n);if(typeof syncCompactPlayerProxy==='function')syncCompactPlayerProxy();publishPlayerState();clearTimeout(volumeTimer);volumeTimer=setTimeout(async()=>{try{await call('volume',n);if(volumeDraft===n)volumeDraft=null;}catch(e){toast(e.message,true);}},300);}
function togglePlayerMute(){if(audio.volume>0||Number($('volume').value)>0){lastNonZeroVolume=Math.max(1,Number($('volume').value)||Math.round(audio.volume*100)||50);setPlayerVolume(0);}else setPlayerVolume(lastNonZeroVolume||50);}
api?.onVolume?.(setPlayerVolume);
api?.onSeek?.(value=>{if(value?.key!==current||typeof value.ratio!=='number'||!Number.isFinite(value.ratio)||value.ratio<0||value.ratio>1||!Number.isFinite(audio.duration)||audio.duration<=0||!audio.seekable.length)return;try{audio.currentTime=audio.duration*value.ratio;VKSoundSeek.progress($('seekWrap'),value.ratio);lastMiniSignature='';publishPlayerState();}catch{}});

function placeQueueCard(){if(matchMedia('(max-width:600px)').matches)$('main').insertBefore($('mobileQueueAnchor'),$('main').firstChild);const target=matchMedia('(max-width:600px)').matches?$('mobileQueueAnchor'):$('queueAnchor');if($('queueCardSlot').parentElement!==target)target.append($('queueCardSlot'));}
window.addEventListener('resize',()=>{if(!uiDormant)placeQueueCard();});
async function openRecommended(id){if(loading||!fx.online||status.state!=='ready')return;const ticket=++albumTicket,accountId=db.profile?.id;loading=true;render();try{const p=await call('recommendationTracks',{id});if(ticket!==albumTicket||accountId!==db.profile?.id)return;await snapshot();if(ticket!==albumTicket||accountId!==db.profile?.id)return;albumPreview=p;albumSource='';recommendationSource=id;go('album:'+p.id);}catch(e){if(e.code!=='CANCELLED')toast(e.message,true);}finally{loading=false;render();}}
async function setUiVisibility({visible,miniVisible:mini=false}){miniVisible=mini;const ticket=++visibilityTicket;if(!visible){if(!uiDormant){savedUiScroll=$('main').scrollTop;cancelWave();uiDormant=true;if(typeof updateMixVisual==='function')updateMixVisual();coverTheme.suspend();clearTimeout(autoRefreshTimer);trackObserver?.disconnect();clearDrag();dismiss();$('queueDialog')?.close();$('fullPlayer')?.close();for(const id of ['tracks','playlistGrid','queueItems','eqBands','shortcutFields']){const root=$(id);if(!root)continue;for(const img of root.querySelectorAll('img')){img.onerror=img.onload=null;img.removeAttribute('src');}root.replaceChildren();}for(const img of document.querySelectorAll('.now-art img,#avatar img,#profileAvatar img'))img.remove();const art=document.querySelector('.now-art');if(art)delete art.dataset.cover;}if(miniVisible){updateCoverTheme();lastMiniSignature='';publishPlayerState();}return;}
 if(uiDormant){try{await snapshot();}catch(e){toast(e.message,true);}if(ticket!==visibilityTicket)return;uiDormant=false;try{render();$('main').scrollTop=savedUiScroll;}catch(error){console.error('VKSound: visibility restore failed',error);uiDormant=false;for(const root of document.querySelectorAll('.sidebar,.workspace'))root.inert=false;toast('Не удалось восстановить интерфейс. Попробуйте свернуть и развернуть окно ещё раз.',true);}}else if(miniVisible){lastMiniSignature='';publishPlayerState();}}
api?.onVisibility?.(data=>setUiVisibility(data).catch(()=>{}));

function updateCoverTheme(){if(uiDormant&&!miniVisible)return;const t=db.rows[current],key=t?.coverKey,url=key&&/^(?:[tpu]:-?[1-9]\d*_[1-9]\d*|[af]:[a-f0-9]{24})$/.test(key)&&db.coverBase?db.coverBase+window.VKSoundCoverPath.file(key)+'?v='+(db.coverRevision||0):'';coverTheme.update({url,enabled:db.settings.coverColors!==false,mode:document.documentElement.dataset.theme});}
function renderMixLauncher(){if(typeof updateMixVisual==='function')updateMixVisual();const panel=$('mixPanel');if(!panel)return;const hasProfile=!!(db.profile||status.profile),visible=hasProfile&&(route==='mix'||(route==='home'&&homeSectionOrder().includes('mix')));panel.hidden=!visible;if(route==='mix'&&hasProfile){const collection=$('collection'),heading=collection.querySelector('.heading');if(heading&&(panel.parentElement!==collection||panel.nextElementSibling!==heading))collection.insertBefore(panel,heading);}else if(route==='home'&&hasProfile){const home=$('homeSections'),anchor=$('mixHomeAnchor');if(!home?.contains(panel)&&panel.parentElement!==anchor)anchor.append(panel);}$('mixLaunch').disabled=mixBusy&&!(mixPlayback&&current);$('mixLaunch').querySelector('.mix-play').replaceChildren(icon(mixPlayback&&current&&!audio.paused?'pause':'play'));const label=mixBusy&&!current?'Загрузка…':mixPlayback&&current?(audio.paused?'Продолжить':'Пауза'):'Слушать';$('mixLaunchLabel').textContent=label;$('mixLaunch').setAttribute('aria-label','VK Микс: '+label.toLowerCase());$('mixBannerStatus').textContent=mixBusy?'Загружаем треки из VK…':mixPlayback?'Очередь дополняется по мере прослушивания':'Персональный поток VK';}


